256	
257	    switch (level) {
258	    case 0: { /* L1 resume */
259	        pid_t pid;
260	        if (read_pid(&pid) != OK) {
261	            return ERROR;
262	        }
263	        if (kill(pid, SIGUSR1) != 0) {
264	            return ERROR;
265	        }
266	        usleep(3000000);
267	        return measure_delta(post_delta);
268	    }
269	    case 1: /* L2 restart, same workload */
270	        stop_task();
271	        if (respawn(RUN_ELF_PATH, mode) != 0) {
272	            return ERROR;
273	        }
274	        usleep(6000000);
275	        return measure_delta(post_delta);
276	    default: /* L3 hotfix deferred with M4; anything above L2 is human */
277	        return ERROR;
278	    }
