298	static int tool_recover_execute_inner(const char *input_json, char *output,
299	    size_t output_size)
300	{
301	    cJSON *root = cJSON_Parse(input_json);
302	    if (!root) {
303	        snprintf(output, output_size,
304	            "{\"result\":\"refused\",\"reason\":\"bad_json\"}");
305	        return ERROR;
306	    }
307	
308	    const char *action = cJSON_GetStringValue(
309	        cJSON_GetObjectItem(root, "action"));
310	    const char *target = cJSON_GetStringValue(
311	        cJSON_GetObjectItem(root, "target"));
312	    bool confirm = cJSON_IsTrue(cJSON_GetObjectItem(root, "confirm"));
313	
314	    if (s_recovering) {
315	        snprintf(output, output_size,
316	            "{\"result\":\"refused\",\"reason\":\"busy\"}");
317	        cJSON_Delete(root);
318	        return OK;
319	    }
320	
321	    /* reset/test are human-only CLI verbs (nsh/vela CLI). They must
322	     * never be reachable through an LLM tool call - refuse explicitly. */
323	    if (action && (strcmp(action, "reset") == 0
324	        || strcmp(action, "test") == 0)) {
325	        snprintf(output, output_size,
326	            "{\"result\":\"refused\",\"reason\":\"cli_only\"}");
327	        cJSON_Delete(root);
328	        return OK;
329	    }
330	
331	    int level = -1;
332	    if (action && strcmp(action, "resume") == 0) level = 0;
333	    else if (action && strcmp(action, "restart") == 0) level = 1;
334	    if (action && strcmp(action, "hotfix") == 0) {
335	        /* M4 (ELF hotfix) is deferred; the rung above L2 is the human */
336	        snprintf(output, output_size,
337	            "{\"result\":\"refused\",\"reason\":\"m4_deferred\"}");
338	        cJSON_Delete(root);
339	        return OK;
340	    }
341	
342	    /* guard: whitelist — nsh/ai_agent/network tasks are untouchable */
343	    if (level < 0 || !target
344	        || (strcmp(target, "buggy_app") != 0
345	            && strcmp(target, "buggy_app_fixed") != 0)) {
346	        snprintf(output, output_size,
347	            "{\"result\":\"refused\",\"reason\":\"whitelist\"}");
348	        audit(target ? target : "?", action ? action : "?",
349	            -1, -1, "refused_whitelist");
350	        cJSON_Delete(root);
351	        return OK;
352	    }
353	
354	    /* guard: needs_human blocks everything until manually cleared */
355	    if (access(NEEDS_HUMAN, F_OK) == 0) {
356	        snprintf(output, output_size,
357	            "{\"result\":\"needs_human\",\"reason\":\"l3_failed\"}");
358	        cJSON_Delete(root);
359	        return OK;
360	    }
361	
362	    /* guard: mode */
363	    int mode = CONFIG_SILOOP_RECOVERY_MODE;
364	    if (mode == 0) {
365	        snprintf(output, output_size,
366	            "{\"result\":\"refused\",\"reason\":\"disabled\"}");
367	        cJSON_Delete(root);
368	        return OK;
369	    }
370	
371	    /* guard: cooldown + hourly cap */
372	    time_t now = time(NULL);
373	    if (s_last_action && now - s_last_action < COOLDOWN_S) {
374	        snprintf(output, output_size,
375	            "{\"result\":\"refused\",\"reason\":\"cooldown\"}");
376	        cJSON_Delete(root);
377	        return OK;
378	    }
379	    if (s_hour_start == 0 || now - s_hour_start >= 3600) {
380	        s_hour_start = now;
381	        s_hour_count = 0;
382	    }
383	    if (s_hour_count >= HOURLY_MAX) {
384	        snprintf(output, output_size,
385	            "{\"result\":\"refused\",\"reason\":\"rate_limit\"}");
386	        cJSON_Delete(root);
387	        return OK;
388	    }
389	
390	    /* guard: independent re-sample — never touch a healthy task */
391	    long pre_delta = -1;
392	    if (measure_delta(&pre_delta) != OK) {
393	        snprintf(output, output_size,
394	            "{\"result\":\"refused\",\"reason\":\"no_heartbeat\"}");
395	        cJSON_Delete(root);
396	        return OK;
397	    }
398	    if (pre_delta > 0) {
399	        snprintf(output, output_size,
400	            "{\"result\":\"refused\",\"reason\":\"already_healthy\"}");
401	        audit(target, action, pre_delta, pre_delta, "refused_healthy");
402	        cJSON_Delete(root);
403	        return OK;
404	    }
405	
406	    /* guard: PID identity - a stale PID file whose number was reused
407	     * must never make us signal a foreign task */
408	    {
409	        pid_t cur_pid;
410	        if (read_pid(&cur_pid) == OK
411	            && verify_pid_target(cur_pid) != OK) {
412	            snprintf(output, output_size,
413	                "{\"result\":\"refused\",\"reason\":\"pid_mismatch\"}");
414	            audit(target, action, pre_delta, -1, "pid_mismatch");
415	            cJSON_Delete(root);
416	            return OK;
417	        }
418	    }
419	
420	    /* confirm mode: first call only returns the plan */
421	    if (mode == 2 && !confirm) {
422	        snprintf(output, output_size,
423	            "{\"result\":\"needs_confirm\",\"action\":\"%s\","
424	            "\"target\":\"%s\",\"pre_delta\":%ld}",
425	            action, target, pre_delta);
426	        cJSON_Delete(root);
427	        return OK;
428	    }
429	
430	    /* dry-run: report the plan, execute nothing */
431	    if (mode == 1) {
432	        snprintf(output, output_size,
433	            "{\"result\":\"dry_run\",\"action\":\"%s\",\"target\":\"%s\","
434	            "\"pre_delta\":%ld}",
435	            action, target, pre_delta);
436	        audit(target, action, pre_delta, -1, "dry_run");
437	        cJSON_Delete(root);
438	        return OK;
439	    }
440	
441	    /* ── walk the ladder from the level the LLM proposed ─────────── */
442	    s_recovering = 1;
443	    static const char *const level_name[2] = { "resume", "restart" };
444	    long post_delta = 0;
445	    int done_level = -1;
446	    int recurred = 0;
447	
448	    for (int lv = level; lv < 2; lv++) {
449	        if (rung(lv, target, &post_delta) != OK) {
450	            /* rung could not run: try the next level */
451	            post_delta = -1;
452	            continue;
453	        }
454	        if (post_delta <= 0) {
455	            continue; /* did not recover here: walk up */
456	        }
457	        /* M3 recurrence watch: hold one heartbeat period, then sample
458	         * again. A fault that comes back inside the window is not
459	         * recovered - walk up (or escalate when the ladder is done).
460	         * Blocks the agent loop for RECUR_OBSERVE_S by design: the
461	         * verdict must not be called before the watch completes. */
462	        sleep(RECUR_OBSERVE_S);
463	        long recur_delta = 0;
464	        if (measure_delta(&recur_delta) == OK && recur_delta > 0) {
465	            done_level = lv;
466	            break;
467	        }
468	        recurred = 1;
469	        post_delta = recur_delta;
470	    }
471	
472	    if (done_level < 0) {
473	        flag_needs_human();
474	        const char *why = recurred ? "recurred" : "needs_human";
475	        snprintf(output, output_size,
476	            "{\"level\":2,\"action\":\"restart\",\"target\":\"%s\","
477	            "\"pre_delta\":%ld,\"post_delta\":%ld,\"result\":\"%s\"}",
478	            target, pre_delta, post_delta, why);
479	        audit(target, action, pre_delta, post_delta, why);
480	    } else {
481	        s_last_action = time(NULL);
482	        s_hour_count++;
483	        snprintf(output, output_size,
484	            "{\"level\":%d,\"action\":\"%s\",\"target\":\"%s\","
485	            "\"pre_delta\":%ld,\"post_delta\":%ld,\"result\":\"recovered\"}",
486	            done_level + 1, level_name[done_level], target,
487	            pre_delta, post_delta);
488	        audit(target, level_name[done_level], pre_delta, post_delta,
489	            "recovered");
490	    }
491	
492	    s_recovering = 0;
493	    cJSON_Delete(root);
494	    return OK;
495	}
