174	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
175	static conn_slot_t* pool_acquire(const char* host, const char* port)
176	{
177	    pthread_mutex_lock(&s_pool_lock);
178	
179	    /* 1. Find an existing valid slot for this host:port */
180	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
181	        conn_slot_t* s = &s_pool[i];
182	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
183	            /* SiliconLoop: drop connections idle past the server's
184	             * keep-alive window. The drain probe below only detects a
185	             * peer that sent close_notify; a server that dropped the
186	             * connection silently is not detected, and the request
187	             * then stalls in TCP retransmission for ~100 seconds.
188	             */
189	            if (pool_now() - s->last_used > AGENT_TLS_POOL_MAX_IDLE_SEC) {
190	                tls_ctx_free(&s->ctx);
191	                s->valid = false;
192	                s->in_use = true;
193	                pthread_mutex_unlock(&s_pool_lock);
194	                return s;
195	            }
196	            s->in_use = true;
197	            pthread_mutex_unlock(&s_pool_lock);
198	            return s;
199	        }
200	    }
201	
202	    /* 2. Find an empty slot */
203	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
204	        if (!s_pool[i].valid && !s_pool[i].in_use) {
205	            s_pool[i].in_use = true;
206	            pthread_mutex_unlock(&s_pool_lock);
207	            return &s_pool[i];
208	        }
209	    }
210	
211	    /* 3. Evict the first non-in-use slot */
212	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
213	        if (!s_pool[i].in_use) {
214	            tls_ctx_free(&s_pool[i].ctx);
215	            s_pool[i].valid = false;
216	            s_pool[i].in_use = true;
217	            pthread_mutex_unlock(&s_pool_lock);
218	            return &s_pool[i];
219	        }
220	    }
221	
222	    pthread_mutex_unlock(&s_pool_lock);
223	    return NULL; /* all slots busy — caller falls back to ephemeral */
224	}
