362	/* ── list_dir (recursive helper) ────────────────────────────── */
363	
364	static size_t list_dir_recursive(const char *dir_path, const char *prefix,
365	                                  char *output, size_t output_size, size_t off,
366	                                  int *count, int depth)
367	{
368	    if (depth > 4) return off;  /* prevent infinite recursion */
369	
370	    DIR *dir = opendir(dir_path);
371	    if (!dir) return off;
372	
373	    struct dirent *ent;
374	    while ((ent = readdir(dir)) != NULL && off < output_size - 1) {
375	        /* Skip . and .. */
376	        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
377	            continue;
378	
379	        char full_path[512];
380	        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, ent->d_name);
381	
382	        if (prefix && strncmp(full_path, prefix, strlen(prefix)) != 0) continue;
383	
384	        struct stat st;
385	        if (stat(full_path, &st) == 0 && S_ISDIR(st.st_mode)) {
386	            off += snprintf(output + off, output_size - off, "%s/\n", full_path);
387	            (*count)++;
388	            off = list_dir_recursive(full_path, prefix, output, output_size, off, count, depth + 1);
389	        } else {
390	            off += snprintf(output + off, output_size - off, "%s\n", full_path);
391	            (*count)++;
392	        }
393	    }
394	    closedir(dir);
395	    return off;
396	}
